/**
 * WebSocket Event Wrapper
 */
export interface WSEvent {
    /**
     * e.g. "ROOM_STATE", "COUNTDOWN", "QUESTION", "ROUND_RESULT", "PODIUM"
     */
    "type": string;
    "payload"?: any;
}

export interface WordDetail {
    "id_word": number;
    "lemma": string;
    "normalized_lemma": string;
    "part_of_speech": string;
    "gender": WordGender;
    "etymology"?: string | null;
    "friendly_blurb"?: string | null;
    "image_url"?: string | null;
    "origin_region"?: Region | null;
    "senses": SenseDetail[] | null;
    "heteronyms": HeteronymItem[] | null;
    "created_at": string;
    "updated_at": string;
}

/**
 * Filtro de exploración paginada (GET /api/v1/words)
 */
export interface WordExploreFilter {
    "q": string;

    /**
     * Ej. 'MX', 'AR', 'ES'
     */
    "region": string;

    /**
     * Ej. 'sustantivo', 'verbo', 'adjetivo', 'modismo'
     */
    "pos": string;

    /**
     * 'A1'..'C2', 'NATIVO'
     */
    "cefr": string;

    /**
     * 'EVERYDAY', 'COMMON', 'RARE', 'SLANG', 'ARCHAIC'
     */
    "frequency": string;

    /**
     * Default true
     */
    "include_taboo": boolean;

    /**
     * Default 1
     */
    "page": number;

    /**
     * Default 20, máx 50
     */
    "limit": number;
}

export enum WordGender {
    /**
     * The Go zero value for the underlying type of the enum.
     */
    $zero = "",

    GenderMale = "MALE",
    GenderFemale = "FEMALE",
    GenderNeutral = "NEUTRAL",
    GenderAmbiguous = "AMBIGUOUS",
};

